/** Work order with status history — GET /api/v1/ops/work-orders/{wo_id} (who may call: holders of ops.workorder.report or ops.workorder.manage). */
export function getWo(wo_id: number): Promise<WorkOrderOut> {
  return api<WorkOrderOut>("GET", `/ops/work-orders/${wo_id}`, undefined);
}

/** Cancel a work order — POST /api/v1/ops/work-orders/{wo_id}/cancel (who may call: holders of ops.workorder.manage). */
export function cancelOpsWorkOrders(wo_id: number, body: OpsReasonIn): Promise<WorkOrderOut> {
  return api<WorkOrderOut>("POST", `/ops/work-orders/${wo_id}/cancel`, body);
}

/** Update an asset / change its status — PUT /api/v1/ops/assets/{asset_id} (who may call: holders of ops.asset.manage). */
export function updateAsset(asset_id: number, body: AssetIn): Promise<AssetOut> {
  return api<AssetOut>("PUT", `/ops/assets/${asset_id}`, body);
}

/** Clear a discharge stage (in order) — POST /api/v1/admissions/{admission_id}/discharge/{stage}/clear (who may call: the permission of the stage: ipd.discharge.clear_pharmacy, clear_nursing, clear_billing or clear_cleaning). */
export function clearStage(admission_id: number, stage: "PharmacyClearance" | "NursingMARVerification" | "BillingSettlement" | "OpsCleaning", body: ClearIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/discharge/${stage}/clear`, body);
}

